-- ==== 20261012000036_quotes_invoices.sql
-- Pro, part 3: quotes and invoices from the trader's phone, and an automatic review request once an invoice is paid.
--
-- * public.trader_billing: the bank details printed on a trader's invoices (account name, sort code, account
--   number). Only the trader, and anyone holding one of their invoice links, sees them. Money never touches us.
-- * public.trade_docs: quotes and invoices. Numbered per listing and kind (Q-0001, INV-0001). Each has a random
--   token: /platform/d/<token> is the customer's copy (no sign-in), where a quote is accepted or declined and an
--   invoice shows how to pay. Lines are [{description, quantity, unit_pence}], totals in pence, no VAT.
--   A quote goes draft → sent → accepted or declined (then it can become an invoice); an invoice goes unpaid → paid
--   (or void). Kept 2 years, then deleted: traders keep their own copies for their records.
-- * Messages to the trader's customers go through the same alert log (public.notifications): a paid invoice's review
--   request (once per invoice, and not to the same number or email for the same trader within 90 days), an emailed
--   quote or invoice, and up to two payment reminders. At most 20 texts a day per listing for these.
-- * Only Pro listings can write. Reading what you've already written stays open after Pro ends.
-- Re-runnable.

-- ---------------------------------------------------------------- bank details
create table if not exists public.trader_billing (
  provider_id uuid primary key references public.providers (id) on delete cascade,
  account_name text not null check (char_length(account_name) between 2 and 70),
  sort_code text not null check (sort_code ~ '^[0-9]{6}$'),
  account_number text not null check (account_number ~ '^[0-9]{8}$'),
  updated_at timestamptz not null default now()
);
alter table public.trader_billing enable row level security;
revoke all on public.trader_billing from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------- quotes and invoices
create table if not exists public.trade_docs (
  id uuid primary key default gen_random_uuid(),
  provider_id uuid not null references public.providers (id) on delete cascade,
  kind text not null check (kind in ('quote', 'invoice')),
  number int not null check (number > 0),
  token uuid not null unique default gen_random_uuid(),
  status text not null check (status in ('draft', 'sent', 'accepted', 'declined', 'unpaid', 'paid', 'void')),
  customer_name text not null check (char_length(customer_name) between 2 and 60),
  customer_phone text check (customer_phone is null or customer_phone ~ '^\+44[1-9][0-9]{8,9}$'),
  customer_email text check (customer_email is null or (char_length(customer_email) <= 254 and customer_email ~ '^[^\s@]+@[^\s@]+\.[^\s@]+$')),
  title text not null check (char_length(title) between 2 and 80),
  lines jsonb not null check (jsonb_typeof(lines) = 'array' and jsonb_array_length(lines) between 1 and 30),
  total_pence bigint not null check (total_pence between 0 and 10000000000),
  notes text check (notes is null or char_length(notes) <= 1000),
  -- Quote: valid until. Invoice: due by.
  until date,
  ask_review boolean not null default true,
  job_request_id uuid references public.job_requests (id) on delete set null,
  quote_id uuid references public.trade_docs (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  answered_at timestamptz,
  paid_at timestamptz,
  constraint trade_docs_status_kind check (
    (kind = 'quote' and status in ('draft', 'sent', 'accepted', 'declined'))
    or (kind = 'invoice' and status in ('draft', 'unpaid', 'paid', 'void'))
  )
);
create unique index if not exists trade_docs_number on public.trade_docs (provider_id, kind, number);
create index if not exists trade_docs_provider_idx on public.trade_docs (provider_id, created_at desc);
alter table public.trade_docs enable row level security;
revoke all on public.trade_docs from public, anon, authenticated, service_role;

-- The alert log takes the messages to customers too (000035's kinds, plus these).
alter table public.notifications drop constraint if exists notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check (kind in (
  'job_request', 'question', 'quote_answered', 'doc_email', 'review_request', 'payment_reminder_1', 'payment_reminder_2'
));

-- ---------------------------------------------------------------- shared checks
-- The caller's own listing with Pro on (to write), or raises not_your_listing / pro_needed.
create or replace function private.my_pro_listing_id(p_provider uuid) returns uuid
language plpgsql stable security definer set search_path = ''
as $$
begin
  perform private.my_listing_id(p_provider);
  if not private.is_pro(p_provider) then
    raise exception 'pro_needed';
  end if;
  return p_provider;
end;
$$;
revoke execute on function private.my_pro_listing_id(uuid) from public, anon, authenticated;

-- Cleaned lines and their total, or raises bad_lines. Each line: a description (1 to 120 characters), a quantity
-- (0.01 to 9999, two decimal places) and a unit price in pence (0 to £100,000).
create or replace function private.doc_lines(p_lines jsonb, out lines jsonb, out total bigint)
language plpgsql immutable set search_path = ''
as $$
declare
  l jsonb;
  v_desc text;
  v_qty numeric;
  v_unit bigint;
begin
  lines := '[]'::jsonb;
  total := 0;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) not between 1 and 30 then
    raise exception 'bad_lines';
  end if;
  for l in select * from jsonb_array_elements(p_lines) loop
    begin
      v_desc := btrim(regexp_replace(coalesce(l ->> 'description', ''), '\s+', ' ', 'g'));
      v_qty := round((l ->> 'quantity')::numeric, 2);
      v_unit := (l ->> 'unit_pence')::bigint;
    exception when others then
      raise exception 'bad_lines';
    end;
    if char_length(v_desc) not between 1 and 120 or v_qty is null or v_qty < 0.01 or v_qty > 9999
       or v_unit is null or v_unit < 0 or v_unit > 10000000 then
      raise exception 'bad_lines';
    end if;
    lines := lines || jsonb_build_array(jsonb_build_object('description', v_desc, 'quantity', v_qty, 'unit_pence', v_unit));
    total := total + round(v_qty * v_unit)::bigint;
  end loop;
end;
$$;
revoke execute on function private.doc_lines(jsonb) from public, anon, authenticated;

create or replace function private.doc_json(d public.trade_docs) returns jsonb
language sql stable security definer set search_path = ''
as $$
  select jsonb_build_object(
    'id', d.id, 'kind', d.kind, 'number', d.number, 'token', d.token, 'status', d.status,
    'customer_name', d.customer_name, 'customer_phone', d.customer_phone, 'customer_email', d.customer_email,
    'title', d.title, 'lines', d.lines, 'total_pence', d.total_pence, 'notes', d.notes, 'until', d.until,
    'ask_review', d.ask_review, 'job_request_id', d.job_request_id, 'quote_id', d.quote_id,
    'created_at', d.created_at, 'sent_at', d.sent_at, 'answered_at', d.answered_at, 'paid_at', d.paid_at,
    'invoice_id', (select i.id from public.trade_docs i where i.quote_id = d.id and i.kind = 'invoice' limit 1)
  );
$$;
revoke execute on function private.doc_json(public.trade_docs) from public, anon, authenticated;

-- ---------------------------------------------------------------- the trader's side
create or replace function public.my_billing(p_provider uuid) returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  v_id uuid := private.my_listing_id(p_provider);
begin
  return (select jsonb_build_object('account_name', b.account_name, 'sort_code', b.sort_code, 'account_number', b.account_number)
          from public.trader_billing b where b.provider_id = v_id);
end;
$$;

-- Raises bad_account_name, bad_sort_code or bad_account_number.
create or replace function public.set_my_billing(p_provider uuid, p_account_name text, p_sort_code text, p_account_number text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid := private.my_pro_listing_id(p_provider);
  v_name text := btrim(regexp_replace(coalesce(p_account_name, ''), '\s+', ' ', 'g'));
  v_sort text := regexp_replace(coalesce(p_sort_code, ''), '[\s-]', '', 'g');
  v_acc text := regexp_replace(coalesce(p_account_number, ''), '\s', '', 'g');
begin
  if char_length(v_name) not between 2 and 70 then
    raise exception 'bad_account_name';
  end if;
  if v_sort !~ '^[0-9]{6}$' then
    raise exception 'bad_sort_code';
  end if;
  if v_acc !~ '^[0-9]{8}$' then
    raise exception 'bad_account_number';
  end if;
  insert into public.trader_billing (provider_id, account_name, sort_code, account_number, updated_at)
  values (v_id, v_name, v_sort, v_acc, now())
  on conflict (provider_id) do update set
    account_name = excluded.account_name, sort_code = excluded.sort_code, account_number = excluded.account_number,
    updated_at = now();
end;
$$;

-- Creates (p_doc without id) or updates a quote or invoice. p_doc: {id?, kind, customer_name, customer_phone,
-- customer_email, title, lines, notes, until, ask_review, job_request_id?}. Only drafts, sent quotes and unpaid
-- invoices can change. Returns the id. Raises bad_kind, bad_customer, bad_phone, bad_email, bad_title, bad_lines,
-- bad_notes, bad_date, locked or not_found.
create or replace function public.save_my_doc(p_provider uuid, p_doc jsonb) returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid := private.my_pro_listing_id(p_provider);
  v_doc public.trade_docs;
  v_kind text := p_doc ->> 'kind';
  v_name text := btrim(regexp_replace(coalesce(p_doc ->> 'customer_name', ''), '\s+', ' ', 'g'));
  v_phone text := nullif(btrim(coalesce(p_doc ->> 'customer_phone', '')), '');
  v_email text := lower(nullif(btrim(coalesce(p_doc ->> 'customer_email', '')), ''));
  v_title text := btrim(regexp_replace(coalesce(p_doc ->> 'title', ''), '\s+', ' ', 'g'));
  v_notes text := nullif(btrim(coalesce(p_doc ->> 'notes', '')), '');
  v_until date;
  v_request uuid;
  v_lines record;
  v_new uuid;
begin
  if v_kind is null or v_kind not in ('quote', 'invoice') then
    raise exception 'bad_kind';
  end if;
  if char_length(v_name) not between 2 and 60 then
    raise exception 'bad_customer';
  end if;
  if v_phone is not null and v_phone !~ '^\+44[1-9][0-9]{8,9}$' then
    raise exception 'bad_phone';
  end if;
  if v_email is not null and (char_length(v_email) > 254 or v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$') then
    raise exception 'bad_email';
  end if;
  if char_length(v_title) not between 2 and 80 then
    raise exception 'bad_title';
  end if;
  if char_length(v_notes) > 1000 then
    raise exception 'bad_notes';
  end if;
  begin
    v_until := nullif(p_doc ->> 'until', '')::date;
  exception when others then
    raise exception 'bad_date';
  end;
  if v_until is not null and (v_until < private.london_today() - 1 or v_until > private.london_today() + 366) then
    raise exception 'bad_date';
  end if;
  select * into v_lines from private.doc_lines(p_doc -> 'lines');
  -- A job request it answers: only one of this listing's own.
  v_request := nullif(p_doc ->> 'job_request_id', '')::uuid;
  if v_request is not null and not exists (select 1 from public.job_requests where id = v_request and provider_id = v_id) then
    v_request := null;
  end if;

  if nullif(p_doc ->> 'id', '') is null then
    perform pg_advisory_xact_lock(hashtext('trade_docs:' || v_id::text || ':' || v_kind));
    delete from public.trade_docs where created_at < now() - interval '2 years';
    insert into public.trade_docs (provider_id, kind, number, status, customer_name, customer_phone, customer_email,
                                   title, lines, total_pence, notes, until, ask_review, job_request_id)
    values (v_id, v_kind,
            coalesce((select max(number) from public.trade_docs where provider_id = v_id and kind = v_kind), 0) + 1,
            case when v_kind = 'quote' then 'draft' else 'unpaid' end,
            v_name, v_phone, v_email, v_title, v_lines.lines, v_lines.total, v_notes, v_until,
            coalesce((p_doc ->> 'ask_review')::boolean, true), v_request)
    returning id into v_new;
    return v_new;
  end if;

  select * into v_doc from public.trade_docs where id = (p_doc ->> 'id')::uuid and provider_id = v_id for update;
  if v_doc.id is null then
    raise exception 'not_found';
  end if;
  if v_doc.status not in ('draft', 'sent', 'unpaid') then
    raise exception 'locked';
  end if;
  update public.trade_docs set
    customer_name = v_name, customer_phone = v_phone, customer_email = v_email, title = v_title,
    lines = v_lines.lines, total_pence = v_lines.total, notes = v_notes, until = v_until,
    ask_review = coalesce((p_doc ->> 'ask_review')::boolean, ask_review), updated_at = now()
  where id = v_doc.id;
  return v_doc.id;
end;
$$;

create or replace function public.my_docs(p_provider uuid) returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  v_id uuid := private.my_listing_id(p_provider);
begin
  return coalesce((
    select jsonb_agg(private.doc_json(d) order by d.created_at desc)
    from (select * from public.trade_docs where provider_id = v_id order by created_at desc limit 50) d
  ), '[]'::jsonb);
end;
$$;

-- One of the caller's quotes or invoices, with the listing it's on: {doc, provider_id, business_name}.
create or replace function public.my_doc(p_doc uuid) returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  v public.trade_docs;
begin
  select * into v from public.trade_docs where id = p_doc;
  if v.id is null then
    raise exception 'not_found';
  end if;
  perform private.my_listing_id(v.provider_id);
  return jsonb_build_object('doc', private.doc_json(v), 'provider_id', v.provider_id,
                            'business_name', (select business_name from public.providers where id = v.provider_id),
                            'slug', (select slug from public.providers where id = v.provider_id));
end;
$$;

-- p_action: 'sent' (a quote went to the customer), 'paid' or 'unpaid' (an invoice), 'void' (an unpaid invoice).
-- Returns the updated doc. Raises bad_action or not_found.
create or replace function public.set_my_doc_status(p_doc uuid, p_action text) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v public.trade_docs;
begin
  select * into v from public.trade_docs where id = p_doc for update;
  if v.id is null then
    raise exception 'not_found';
  end if;
  perform private.my_listing_id(v.provider_id);
  if p_action = 'sent' and v.kind = 'quote' and v.status in ('draft', 'sent') then
    update public.trade_docs set status = 'sent', sent_at = coalesce(sent_at, now()), updated_at = now() where id = v.id;
  elsif p_action = 'paid' and v.kind = 'invoice' and v.status = 'unpaid' then
    update public.trade_docs set status = 'paid', paid_at = now(), updated_at = now() where id = v.id;
  elsif p_action = 'unpaid' and v.kind = 'invoice' and v.status = 'paid' then
    update public.trade_docs set status = 'unpaid', paid_at = null, updated_at = now() where id = v.id;
  elsif p_action = 'void' and v.kind = 'invoice' and v.status = 'unpaid' then
    update public.trade_docs set status = 'void', updated_at = now() where id = v.id;
  elsif p_action = 'invoice_sent' and v.kind = 'invoice' then
    update public.trade_docs set sent_at = coalesce(sent_at, now()), updated_at = now() where id = v.id;
  else
    raise exception 'bad_action';
  end if;
  select * into v from public.trade_docs where id = p_doc;
  return private.doc_json(v);
end;
$$;

-- An invoice from an accepted quote (the same customer and lines, due in 14 days). Returns its id; a second call
-- returns the same invoice. Raises not_found, not_accepted or pro_needed.
create or replace function public.invoice_from_quote(p_quote uuid) returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  q public.trade_docs;
  v_id uuid;
begin
  select * into q from public.trade_docs where id = p_quote and kind = 'quote';
  if q.id is null then
    raise exception 'not_found';
  end if;
  perform private.my_pro_listing_id(q.provider_id);
  if q.status <> 'accepted' then
    raise exception 'not_accepted';
  end if;
  perform pg_advisory_xact_lock(hashtext('trade_docs:' || q.provider_id::text || ':invoice'));
  select id into v_id from public.trade_docs where quote_id = q.id and kind = 'invoice';
  if v_id is not null then
    return v_id;
  end if;
  insert into public.trade_docs (provider_id, kind, number, status, customer_name, customer_phone, customer_email,
                                 title, lines, total_pence, notes, until, ask_review, job_request_id, quote_id)
  values (q.provider_id, 'invoice',
          coalesce((select max(number) from public.trade_docs where provider_id = q.provider_id and kind = 'invoice'), 0) + 1,
          'unpaid', q.customer_name, q.customer_phone, q.customer_email, q.title, q.lines, q.total_pence, q.notes,
          private.london_today() + 14, q.ask_review, q.job_request_id, q.id)
  returning id into v_id;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------- the customer's copy (service role)
-- {doc, business_name, slug, phone, bank} for /platform/d/<token>, or null. bank only on an invoice.
create or replace function public.public_doc(p_token uuid) returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  v public.trade_docs;
  p public.providers;
begin
  select * into v from public.trade_docs where token = p_token and status <> 'draft';
  if v.id is null then
    return null;
  end if;
  select * into p from public.providers where id = v.provider_id;
  return jsonb_build_object(
    'doc', private.doc_json(v) - 'customer_phone' - 'customer_email' - 'job_request_id' - 'token' - 'ask_review',
    'business_name', p.business_name,
    'slug', case when p.status = 'live' then p.slug end,
    'phone', p.phone_e164,
    'bank', case when v.kind = 'invoice' then (
      select jsonb_build_object('account_name', b.account_name, 'sort_code', b.sort_code, 'account_number', b.account_number)
      from public.trader_billing b where b.provider_id = v.provider_id) end
  );
end;
$$;

-- The customer accepts or declines a sent quote. Returns {result: 'ok' | 'already' | 'unavailable', status}.
create or replace function public.answer_quote(p_token uuid, p_accept boolean) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v public.trade_docs;
begin
  select * into v from public.trade_docs where token = p_token and kind = 'quote' for update;
  if v.id is null or v.status = 'draft' then
    return jsonb_build_object('result', 'unavailable');
  end if;
  if v.status <> 'sent' then
    return jsonb_build_object('result', 'already', 'status', v.status);
  end if;
  update public.trade_docs
  set status = case when p_accept then 'accepted' else 'declined' end, answered_at = now(), updated_at = now()
  where id = v.id;
  return jsonb_build_object('result', 'ok', 'status', case when p_accept then 'accepted' else 'declined' end,
                            'id', v.id);
end;
$$;

-- ---------------------------------------------------------------- messages
-- Claims the trader's alert that a quote was answered (000035's caps and once-only rule).
create or replace function public.claim_quote_answer_alert(p_doc uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v public.trade_docs;
begin
  select * into v from public.trade_docs where id = p_doc and kind = 'quote' and status in ('accepted', 'declined');
  if v.id is null then
    return null;
  end if;
  return jsonb_build_object('doc', private.doc_json(v), 'send', private.claim_alerts('quote_answered', v.id, array[v.provider_id]));
end;
$$;

-- Claims a message to the customer on a quote or invoice: p_kind 'review_request' (a paid invoice that asks for a
-- review, once, and not to the same number or email for this trader within 90 days), 'payment_reminder_1' or
-- '_2' (an unpaid invoice past its due date), or 'doc_email' (the trader's "Email it"; email only). Texts go to a
-- mobile only; at most 20 texts to customers a day per listing. Returns {doc, business_name, slug, send} or null.
create or replace function private.claim_customer_message(p_kind text, p_doc uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v public.trade_docs;
  v_out jsonb := '[]'::jsonb;
  v_ch text;
  v_to text;
  v_id uuid;
begin
  select * into v from public.trade_docs where id = p_doc;
  if v.id is null then
    return null;
  end if;
  if p_kind = 'review_request' and not (v.kind = 'invoice' and v.status = 'paid' and v.ask_review) then
    return null;
  end if;
  if p_kind like 'payment_reminder_%' and not (v.kind = 'invoice' and v.status = 'unpaid') then
    return null;
  end if;
  if p_kind = 'doc_email' and v.status = 'draft' then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtext('claim_alerts:' || v.provider_id::text));
  foreach v_ch in array array['sms', 'email'] loop
    v_to := case v_ch when 'sms' then case when v.customer_phone ~ '^\+447' then v.customer_phone end
                      else v.customer_email end;
    continue when v_to is null or (p_kind = 'doc_email' and v_ch = 'sms');
    continue when v_ch = 'sms' and (select count(*) from public.notifications n
                   where n.provider_id = v.provider_id and n.channel = 'sms'
                     and n.kind in ('review_request', 'payment_reminder_1', 'payment_reminder_2')
                     and n.created_at > now() - interval '24 hours') >= 20;
    continue when p_kind = 'review_request' and exists (
      select 1 from public.notifications n
      where n.provider_id = v.provider_id and n.kind = 'review_request' and n.to_addr = v_to
        and n.created_at > now() - interval '90 days');
    insert into public.notifications (provider_id, kind, ref_id, channel, to_addr)
    values (v.provider_id, p_kind, v.id, v_ch, v_to)
    on conflict (kind, ref_id, provider_id, channel) do nothing
    returning id into v_id;
    if v_id is not null then
      v_out := v_out || jsonb_build_array(jsonb_build_object('id', v_id, 'provider_id', v.provider_id, 'channel', v_ch, 'to', v_to));
    end if;
    v_id := null;
  end loop;
  return jsonb_build_object('doc', private.doc_json(v),
                            'business_name', (select business_name from public.providers where id = v.provider_id),
                            'slug', (select slug from public.providers where id = v.provider_id and status = 'live'),
                            'send', v_out);
end;
$$;
revoke execute on function private.claim_customer_message(text, uuid) from public, anon, authenticated;

-- The server's wrapper (service role): the review request after "Mark as paid", or a reminder.
create or replace function public.claim_customer_message(p_kind text, p_doc uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
begin
  if p_kind is null or p_kind not in ('review_request', 'payment_reminder_1', 'payment_reminder_2', 'doc_email') then
    raise exception 'bad_kind';
  end if;
  return private.claim_customer_message(p_kind, p_doc);
end;
$$;

-- Unpaid invoices due a payment reminder (service role, for the daily job): the first 3 days after the due date,
-- the second 7 days after the first. Returns [{id, kind}].
create or replace function public.due_payment_reminders() returns jsonb
language sql stable security definer set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind)), '[]'::jsonb)
  from (
    select d.id,
           case when not exists (select 1 from public.notifications n where n.ref_id = d.id and n.kind = 'payment_reminder_1')
                then 'payment_reminder_1' else 'payment_reminder_2' end as kind
    from public.trade_docs d
    where d.kind = 'invoice' and d.status = 'unpaid' and d.until is not null
      and d.until <= private.london_today() - 3
      and (d.customer_email is not null or d.customer_phone ~ '^\+447')
      and not exists (select 1 from public.notifications n where n.ref_id = d.id and n.kind = 'payment_reminder_2')
      and not exists (select 1 from public.notifications n where n.ref_id = d.id and n.kind = 'payment_reminder_1'
                      and n.created_at > now() - interval '7 days')
    limit 200
  ) x;
$$;

-- ---------------------------------------------------------------- grants
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.public_doc(uuid)',
    'public.answer_quote(uuid, boolean)',
    'public.claim_quote_answer_alert(uuid)',
    'public.claim_customer_message(text, uuid)',
    'public.due_payment_reminders()'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.my_billing(uuid)',
    'public.set_my_billing(uuid, text, text, text)',
    'public.save_my_doc(uuid, jsonb)',
    'public.my_docs(uuid)',
    'public.my_doc(uuid)',
    'public.set_my_doc_status(uuid, text)',
    'public.invoice_from_quote(uuid)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000036', 'quotes_invoices') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
declare
  f text;
  t text;
begin
  foreach f in array array['save_my_doc', 'my_docs', 'my_doc', 'set_my_doc_status', 'invoice_from_quote', 'set_my_billing',
                           'public_doc', 'answer_quote', 'claim_customer_message', 'due_payment_reminders'] loop
    if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                   where n.nspname = 'public' and p.proname = f) then
      raise exception 'Quotes check failed: function public.% is missing', f;
    end if;
  end loop;
  foreach t in array array['trade_docs', 'trader_billing'] loop
    if not (select relrowsecurity from pg_class where oid = ('public.' || t)::regclass) then
      raise exception 'Quotes check failed: row level security is off on public.%', t;
    end if;
    if has_table_privilege('anon', 'public.' || t, 'select') or has_table_privilege('authenticated', 'public.' || t, 'select') then
      raise exception 'Quotes check failed: public.% is readable without the server', t;
    end if;
  end loop;
  if has_function_privilege('anon', 'public.public_doc(uuid)', 'execute')
     or not has_function_privilege('service_role', 'public.public_doc(uuid)', 'execute') then
    raise exception 'Quotes check failed: public_doc is not server only';
  end if;
end
$verify$;

commit;

select 'Quotes and invoices database changes applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000036')) as migrations_recorded;
